arguments.argument:
if !sys_mouse.mouse_check and sys_mouse.mouse_sie=0
{
    if !click_check or global.player_control!=player or sys_mouse.vab_unit>1
    {
        if sk_in_fog(x, y, 0)
        {
            for(i=0; i!=sys_mouse.vab_unit; i+=1){if instance_number(sys_mouse.vab_unit_id[i]){sys_mouse.vab_unit_id[i].click_check=0}}
            click_check=1
            sys_mouse.vab_unit=1
            sys_mouse.vab_unit_id[0]=id
        }
    }
    else
    {
        var c_check;
        c_check=0
        with(obj_unit)
        {
            if player=other.player and unit_id=other.unit_id and drag_ok=1
            {
                if distance_to_point(mouse_x, mouse_y)<300
                {
                    if !c_check
                    {
                        for(i=0; i!=sys_mouse.vab_unit; i+=1){if instance_number(sys_mouse.vab_unit_id[i]){sys_mouse.vab_unit_id[i].click_check=0}}
                        sys_mouse.vab_unit=0
                        c_check=1
                    }
                    click_check=1
                    sys_mouse.vab_unit_id[sys_mouse.vab_unit]=id
                    sys_mouse.vab_unit+=1
                    if sys_mouse.vab_unit>7{break}
                }
            }
        }
    }
}
